use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path,process::Command};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-stack-lifetimes176";const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-11-10-g2-stack-lifetimes176";
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}fn walk(p:&Path,root:&Path,v:&mut Vec<String>){for e in fs::read_dir(p).unwrap(){let p=e.unwrap().path();if p.is_dir(){walk(&p,root,v)}else{v.push(p.strip_prefix(root).unwrap().to_str().unwrap().to_owned())}}}
fn main(){assert!(!Path::new(&format!("{R}/publication.json")).exists());let idx:Value=serde_json::from_slice(&fs::read(format!("{D}/artifacts/archive-index.json")).unwrap()).unwrap();let members=idx["members"].as_object().unwrap();for(p,v)in members{assert_eq!(hash(format!("{R}/publication-roundtrip/{p}")),v["sha256"]);}let mut unpacked=vec![];walk(Path::new(&format!("{R}/publication-roundtrip")),Path::new(&format!("{R}/publication-roundtrip")),&mut unpacked);assert_eq!(unpacked.len(),members.len());
 let note="# Publication finalization\n\nThe original publisher passed input/receipt checks, six independent ELF/MMAP2 bias checks, archive construction and roundtrip/member checks. It then exited101 when checking the README's SHA256SUMS link before creating that file. No performance data, result, archive or successful analysis is rerun. This narrow finisher checks existing roundtrip members, records this note and its source, creates checksums, then validates all README links. The archived original publisher source retains the ordering bug.\n\nAn unused-import compiler warning occurred in the first publisher build. The comparison file's object/rows schema was corrected before its first execution. Both are publication-tool details and change no scientific result.\n";
 fs::write(format!("{R}/publication-repair.md"),note).unwrap();fs::write(format!("{D}/artifacts/publication-repair.md"),note).unwrap();fs::copy(format!("{R}/finish-publication.rs"),format!("{D}/artifacts/finish-publication.rs")).unwrap();let mut readme=fs::read_to_string(format!("{D}/README.md")).unwrap();readme.push_str("\n[Publication finalization](artifacts/publication-repair.md), [finisher source](artifacts/finish-publication.rs).\n");fs::write(format!("{D}/README.md"),&readme).unwrap();
 let mut files=vec![];walk(Path::new(D),Path::new(D),&mut files);files.sort();assert!(!files.iter().any(|s|s=="SHA256SUMS"));let sums=files.iter().map(|p|format!("{}  {p}\n",hash(Path::new(D).join(p)))).collect::<String>();fs::write(format!("{D}/SHA256SUMS"),sums).unwrap();let mut links=0;for part in readme.split("](").skip(1){let target=part.split(')').next().unwrap();assert!(Path::new(D).join(target).is_file(),"{target}");links+=1;}
 let out=Command::new("sha256sum").args(["-c","SHA256SUMS"]).current_dir(D).output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let result=json!({"passed":true,"archive_members":members.len(),"links_checked":links,"workflow_receipts":16,"retained_workflow_failures":2,"independent_ELF_MMAP2_bias_checks":6,"roundtrip_and_checksums":true,"publication_order_failure_retained":true,"report":format!("{D}/README.md"),"performance_measured":false,"native_selected":false,"adopted":false,"goal_active":true,"goal_complete":false});fs::write(format!("{R}/publication.json"),serde_json::to_vec_pretty(&result).unwrap()).unwrap();println!("{result}");
}
